<script setup>
import { computed, ref } from 'vue'
import { Plus, Search, Pencil, UsersRound, ArrowUpRight, Wallet, Copy, Link2 } from 'lucide-vue-next'
import { useAppStore } from '../stores/app'
import { api } from '../api'
import { money, initials } from '../utils/format'
import BaseModal from '../components/BaseModal.vue'
import PaymentTable from '../components/PaymentTable.vue'
import GoalProgress from '../components/GoalProgress.vue'
const store = useAppStore(), search = ref(''), filter = ref('all'), editing = ref(null), selected = ref(null), busy = ref(false), error = ref(''), access = ref(null), accessError = ref('')
const list = computed(()=>store.employees.filter(e=>(filter.value==='all'||e.active===(filter.value==='active'))&&e.name.toLowerCase().includes(search.value.toLowerCase())))
const total = id => store.successful.filter(p=>p.employeeId===id).reduce((s,p)=>s+p.amount,0)
const selectedPayments = computed(()=>store.sortedPayments.filter(p=>p.employeeId===selected.value?.id))
function edit(e) { error.value=''; editing.value = e ? { ...e } : { name:'', role:'Официант', active:true } }
async function save() { busy.value=true; error.value=''; const isNew=!editing.value.id; try { const employee=await api.saveEmployee(editing.value); await store.load(); editing.value=null; if(isNew)openAccess(employee); store.notify(isNew?'Сотрудник добавлен. Передайте ему приглашение.':'Изменения в команде сохранены') } catch(e) { error.value=e.message } finally { busy.value=false } }
const accessUrl = computed(() => access.value ? new URL(`/register?role=employee&invite=${access.value.accessToken}`,window.location.origin).href : '')
function openAccess(employee) { access.value=employee; accessError.value='' }
async function copyAccess(type='link') { try { await navigator.clipboard.writeText(type==='code'?access.value.accessToken:accessUrl.value); store.notify(type==='code'?'Код приглашения скопирован':'Ссылка приглашения скопирована') } catch { accessError.value='Выделите код или ссылку и скопируйте вручную.' } }
</script>
<template><div class="page-heading"><div><h1>Команда<span class="heading-dot">.</span></h1><p>Сотрудники ресторана, аккаунты и полученные чаевые.</p></div><button class="btn btn-primary" @click="edit()"><Plus :size="18" />Добавить сотрудника</button></div><div class="info-banner"><Link2 :size="18"/><span><strong>Как сотруднику получить аккаунт?</strong> Добавьте его в команду, затем нажмите «Приглашение сотрудника» на карточке. Передайте код или ссылку — они нужны в форме регистрации с ролью «Сотрудник».</span></div><div class="toolbar"><div class="tabs"><button :class="{active:filter==='all'}" @click="filter='all'">Все <span>{{ store.employees.length }}</span></button><button :class="{active:filter==='active'}" @click="filter='active'">Активные</button><button :class="{active:filter==='inactive'}" @click="filter='inactive'">Неактивные</button></div><label class="search-input"><Search :size="18"/><input v-model="search" placeholder="Найти сотрудника" aria-label="Поиск сотрудника"></label></div><div v-if="!list.length" class="panel empty"><UsersRound :size="36"/><h3>{{ store.employees.length ? 'Никого не нашли' : 'В команде пока никого нет' }}</h3><p>{{ store.employees.length ? 'Попробуйте изменить поиск или фильтр.' : 'Добавьте сотрудника и пригласите его зарегистрировать личный аккаунт.' }}</p><button class="btn btn-primary" @click="edit()">Добавить сотрудника</button></div><div class="employee-grid"><article v-for="e in list" :key="e.id" class="panel employee-card"><div class="employee-card-top"><span class="avatar large" :class="e.color">{{ initials(e.name) }}</span><button class="icon-btn" @click="edit(e)" :aria-label="`Редактировать ${e.name}`"><Pencil :size="17"/></button></div><h2>{{ e.name }}</h2><p class="muted">{{ e.role }}</p><span class="status" :class="e.active?'success':'cancelled'"><i></i>{{ e.active?'Активен':'Неактивен' }}</span><span v-if="e.registered" class="account-connected">Аккаунт подключён</span><GoalProgress :goal="e.goal"/><p v-if="!e.goal" class="employee-no-dream">Цель пока не указана</p><div class="employee-sum"><div><span>Чаевые за всё время</span><strong>{{ money(total(e.id)) }}</strong></div><Wallet :size="22"/></div><button class="text-link" @click="selected=e">Статистика сотрудника<ArrowUpRight :size="17"/></button><button v-if="e.active && !e.registered" class="text-link employee-access" @click="openAccess(e)"><Link2 :size="15"/>Приглашение сотрудника</button></article></div><BaseModal v-if="editing" :title="editing.id?'Редактировать сотрудника':'Новый сотрудник'" subtitle="После добавления отправьте сотруднику приглашение." @close="!busy && (editing=null)"><form @submit.prevent="save" class="form-stack"><label>Имя и фамилия<input v-model="editing.name" required minlength="2" maxlength="80" placeholder="Например, Анна Смирнова"></label><label>Должность<input v-model="editing.role" required maxlength="60" placeholder="Официант"></label><label v-if="editing.id" class="checkbox-label"><input type="checkbox" v-model="editing.active">Принимает чаевые<span class="muted">Неактивный сотрудник скрыт от гостей и не принимает чаевые. История сохранится.</span></label><p v-if="error" class="error-text" role="alert">{{ error }}</p><button class="btn btn-primary" :disabled="busy">{{ busy?'Сохраняем…':'Сохранить сотрудника' }}</button></form></BaseModal><BaseModal v-if="selected" :title="selected.name" :subtitle="selected.role" @close="selected=null"><GoalProgress :goal="selected.goal"/><div class="employee-detail"><span>Успешные чаевые</span><strong>{{ money(total(selected.id)) }}</strong><span>{{ selectedPayments.filter(p=>p.status==='success').length }} успешных платежей</span></div><PaymentTable :payments="selectedPayments.slice(0,10)" :employee-name="store.employeeName" /></BaseModal><BaseModal v-if="access" title="Приглашение сотрудника" :subtitle="access.name" @close="access=null"><div class="form-stack"><p class="muted small-text">Отправьте ссылку сотруднику. Он создаст аккаунт с собственным email и паролем и получит доступ только к своим чаевым и целям. Приглашение можно использовать один раз.</p><label>Код приглашения<input :value="access.accessToken" readonly class="invitation-code"></label><button class="btn btn-primary" @click="copyAccess('code')"><Copy :size="17"/>Скопировать код</button><label>Или передайте готовую ссылку<input :value="accessUrl" readonly></label><p v-if="accessError" class="error-text">{{ accessError }}</p><button class="btn btn-outline" @click="copyAccess('link')"><Copy :size="17"/>Скопировать ссылку</button><a :href="accessUrl" target="_blank" rel="noopener" class="btn btn-outline">Открыть регистрацию<ArrowUpRight :size="17"/></a></div></BaseModal></template>
